		jobPackInstructionsResponseWrapper.jobPackInstructionsResponses.Remove(jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[jobPackInstructionsResponseWrapper.jobPackInstructionsResponses.Count - 1]);
