		if (jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[0].blob_url != "" && jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[0].blob_url != null) {
			stepByStepGuideTextPanel.SetActive(false);
			stepByStepGuidePanelWithVideo.SetActive(true);
			videoPlayer.url = jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[0].blob_url;
			videoPlayer.Play();
		} else {
			stepByStepGuideTextPanel.SetActive(true);
			stepByStepGuidePanelWithVideo.SetActive(false);
		}

		for (int i = 0; i < jobPackInstructionsResponseWrapper.jobPackInstructionsResponses.Count; i++) {
			//switch (i) {
			//	default:
			//	GameObject item = Instantiate(stepByStepGuideTextItemPrefab, guideItemHolder);
			//	StepByStepGuideTextItem itemScript = item.GetComponent<StepByStepGuideTextItem>();
			//	itemScript.descriptionTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].message;
			//	break;
			//	case 1:
			//	GameObject item2 = Instantiate(StepByStepGuideTextAndVideoItemPrefab, guideItemHolder);
			//	StepByStepGuideTextAndVideoItem itemScript2 = item2.GetComponent<StepByStepGuideTextAndVideoItem>();
			//	itemScript2.descriptionTextField.text = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].message;
			//	itemScript2.videoPlayer.url = eTaskInstructionsResponseWrapper.eTaskInstructionsResponses[i].blob_url;
			//	itemScript2.videoPlayer.Play();
			//	break;
			//}
		}

		newInstruction = new List<JobpackInstruction> {
			jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[0],
			jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[1],
			jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[2],
			jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[3],
			jobPackInstructionsResponseWrapper.jobPackInstructionsResponses[4],
			new JobpackInstruction {
				message = "Step 6: Remove side cover of lube oil reservoir tank, place absorbent pad and proceed with cleaning activities. Close side cover once the lube oil reservoir tank is properly cleaned. Proceed to perform flushing activities"
			},
