	}

	private void SwitchPanel(int direction) {
		if (newInstruction.Count == 0) return;
		currentIndex += direction;
		if (currentIndex >= newInstruction.Count) {
			currentIndex = newInstruction.Count - 1;
		} else if (currentIndex < 0) {
			currentIndex = 0;
		}
		DisplayPanel(currentIndex);
		UpdateButtonStates(currentIndex, newInstruction.Count);
	}

	bool hasBeenRotated = false;
	//bool panelHasBeenRotated = false;

	void DisplayPanel(int index) {
		stepByStepGuideTextOnly_HeaderTextField.text = (index + 1).ToString();
		stepByStepGuideImageText_HeaderTextField.text = (index + 1).ToString();
		stepByStepGuideVideoText_HeaderTextField.text = (index + 1).ToString();
		stepByStepGuideTextOnly_TextField.text = ShowProperText(newInstruction[index].message);
		stepByStepGuideImageText_TextField.text = ShowProperText(newInstruction[index].message);
		stepByStepGuideVideoText_TextField.text = ShowProperText(newInstruction[index].message);
