		switch (index) {
			default:
			if (hasBeenRotated) videoPlayer.transform.Rotate(0, 0, 180);
			hasBeenRotated = false;
			break;
			case 1:
			videoPlayer.transform.Rotate(0, 0, 180);
			hasBeenRotated = true;
			break;
