			//stepByStepGuidePanelParentObj.transform.Rotate(0, 90, 0);
			break;
			case 4:
			pageManager.cameraPanel.StopAutoTakePhotoForActiveValidation();
			UIInteractable(true);
			startTrackingPoint = true;
			drainPoint.SetActive(false);
			drainPointCollider.enabled = false;
			coolerPoint.SetActive(true);
			coolerPointCollider.enabled = true;
			outOfPointWarningText.text = "Please go to cooler point!";
			//stepByStepGuidePanelParentObj.transform.position = coolerPointPanelPosition.position;
			//if (panelHasBeenRotated) {
			//panelHasBeenRotated = false;
			//stepByStepGuidePanelParentObj.transform.Rotate(0, -90, 0);
			//}
			break;
			case 6:
			pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
			UIInteractable(false);

                //pageManager.cameraPanel.currentPhotoMessageInput = "This image show a cylindrical filters, is it a old filter or a new filter? The color of old filter appears to have a reddish-brown tone, likely due to discoloration caused by prolonged use, dirt, or oxidation. The new filter has a metallic gray appearance, typical of stainless steel or aluminum.\r\nanswer in json format {filter_status:text} old or new";
