            pageManager.cameraPanel.cameraText.text = "Please take photo of the filter!";
			startTrackingPoint = false;
			drainPoint.SetActive(false);
			drainPointCollider.enabled = false;
			coolerPoint.SetActive(false);
			coolerPointCollider.enabled = false;
			//stepByStepGuidePanelParentObj.transform.position = defaultPanelPosition;
			break;
			default:
