	void VideoPrepareComplete(int index) {
		videoPlayer.Play();
		videoPlayer.prepareCompleted -= delegate { VideoPrepareComplete(index); };
	}

	void TaskCompleted() {
		currentIndex = 0;
		UpdateButtonStates(currentIndex, newInstruction.Count);

		isStepInForTheFirstTime = false;
		stepByStepGuidePanelParentObj.SetActive(false);

		videoPlayer.renderMode = VideoRenderMode.RenderTexture;
		videoPlayer.targetTexture.Release(); // Ensure the texture is released when switching videos.

		stepByStepGuideTextPanel.SetActive(false);
		stepByStepGuideTextOnly_HeaderTextField.text = "";
		stepByStepGuideTextOnly_TextField.text = "";

		stepByStepGuidePanelWithImage.SetActive(false);
		stepByStepGuideImageText_HeaderTextField.text = "";
		stepByStepGuideImageText_TextField.text = "";
		imageDisplay.texture = null;

		stepByStepGuidePanelWithVideo.SetActive(false);
		videoPlayer.url = null;
		videoPlayer.Stop();
		stepByStepGuideVideoText_HeaderTextField.text = "";
		stepByStepGuideVideoText_TextField.text = "";

		completePanel.SetActive(true);
		completePanelButton.button.enabled = true;
	}

	protected override void PerformActionAfterCompleteTaskCountdown() {
		base.PerformActionAfterCompleteTaskCountdown();
		StopCountdown();
		string passInParams = JsonUtility.ToJson(new JobPackStatus(pageManager.jobTaskPanel.taskNo, "Completed"));
		StartCoroutine(ApiManager.instance.APICallPut(
			APIPutMiddlePath.APIPutMiddlePathList[(int)APIPutMiddlePathEnum.JobpackStatus],
			passInParams,
			() => {
				var queryParamsGetUserAttributes = new Dictionary<string, string> {
						{"user_id",  pageManager.managerControlScript.loginScript.userAccountDetails.user_id.ToString() }
				};
				ApiManager.instance.APICallGETWithParameters(
				APIGetMiddlePath.APIGetMiddlePathList[(int)APIGetMiddlePathEnum.UserAttributes],
				queryParamsGetUserAttributes,
				() => {
					completePanel.SetActive(false);
					pageManager.handMenuPanelsManager.stillCanShowMoreOptionDetails = true;
				},
				(DownloadHandler downloadHandler) => {
					isStepInForTheFirstTime = false;
					pageManager.managerControlScript.loginScript.ProcessGetUserAttributesResponse(downloadHandler);
					pageManager.homePagePanel.homePanel.SetActive(true);
				});
			}
			));
	}

	#region Photo Taken
	void PhotoTaken(ActiveValidations parameters) {
		if (pageManager.managerControlScript.loginScript.playerType != PlayerType.MT) return;
		string jsonDataActiveValidation = JsonUtility.ToJson(parameters);

		switch (currentIndex) {
			case 0:
			string[] imageArray = { meterSamplePhoto, parameters.base64_image };
			ActiveValidationsOpenaiMultiple parametersWithMultipleImages = new ActiveValidationsOpenaiMultiple(
				pageManager.cameraPanel.currentPhotoMessageInput,
				imageArray);
			string jsonDataActiveValidationForMultipleImages = JsonUtility.ToJson(parametersWithMultipleImages);
			Debug.Log($"Lube Oil Change, Sending Data To OpenAI on step {currentIndex}: {pageManager.cameraPanel.currentPhotoMessageInput}");
			Debug.Log($"Result Photo: {parameters.base64_image}");
			StartCoroutine(
				ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenaiMultiple],
				jsonDataActiveValidationForMultipleImages,
				() => {

				},
				CheckPhoto
				));
			break;
			default:
                string[] imageArray2 = { oldFilterSamplePhoto, newFilterSamplePhoto, parameters.base64_image };
                ActiveValidationsOpenaiMultiple parametersWithMultipleImages2 = new ActiveValidationsOpenaiMultiple(
                    pageManager.cameraPanel.currentPhotoMessageInput,
                    imageArray2);
                string jsonDataActiveValidationForMultipleImages2 = JsonUtility.ToJson(parametersWithMultipleImages2);
                Debug.Log($"Lube Oil Change, Sending Data To OpenAI on step {currentIndex}: {jsonDataActiveValidation}");
			Debug.Log($"Result Photo: {parameters.base64_image}");
			StartCoroutine(
           //ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenAi],
           //jsonDataActiveValidation,
           ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenaiMultiple],
           jsonDataActiveValidationForMultipleImages2,
            () => {

			},
			CheckPhoto
			));
			break;
		}
	}

	void CheckPhoto(DownloadHandler returnedItems) {
		Debug.Log($"Lube Oil Change, Result Received From OpenAI on step {currentIndex}: {returnedItems.text}");
		lubeOilChangeActiveValidation = JsonUtility.FromJson<LubeOilChangeActiveValidation>(returnedItems.text);
		if (lubeOilChangeActiveValidation != null) {
			if (CheckCondition(lubeOilChangeActiveValidation)) {
				AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationSuccessSfx);
				StartCoroutine(StartCountdown(5, () => {
					switch (currentIndex) {
						default:
						SwitchPanel(1);
						break;
						case 6:
						TaskCompleted();
						StartCountdownAfterCompleted();
						break;
					}
					pageManager.cameraPanel.cameraPanel.SetActive(false);
					pageManager.cameraPanel.StopAutoTakePhotoForActiveValidation();
				}));
			} else {
				AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
				StartCoroutine(StartCountdown(5, () => {
					pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
				}));
			}
		} else {
			pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
			pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
			pageManager.aiValidationPanel.aiValidateDetailsText.text = "No Data";
			AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
			StartCoroutine(StartCountdown(5, () => {
				pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
			}));
		}
	}

	bool CheckCondition(LubeOilChangeActiveValidation itemToCheck) {
		pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
		if (currentIndex == 0) {
			if(itemToCheck.isMeterDetected)
			{
                if (itemToCheck.pressure_gauge_reading == "0" || itemToCheck.isMeterPointingBefore10)
                {
                    pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Success";
                    pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: 0 barg";
                    return true;
                }
                else
                {
                    pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
                    pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: " + itemToCheck.pressure_gauge_reading.ToString();
                    return false;
                }
			}
			else
			{
                pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
                pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: Undetected";
                return false;
            }
			
			//if (itemToCheck.pressure_gauge_reading != "0") {
			//	if (itemToCheck.pressure_gauge_reading != "" && itemToCheck.pressure_gauge_reading != null) {
			//		pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
			//		pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: " + itemToCheck.pressure_gauge_reading.ToString();
			//	} else {
			//		pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
			//		pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: Undetected";
			//	}
			//	return false;
			//} else {
			//	pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Success";
			//	pageManager.aiValidationPanel.aiValidateDetailsText.text = "Pressure reading: " + itemToCheck.pressure_gauge_reading.ToString() + " barg";
			//	return true;
			//}
		} else if (currentIndex == 6) {
			if (itemToCheck.filter_status.ToLower() == "new" || itemToCheck.filter_status.ToLower() == "new filter" || itemToCheck.filter_status.ToLower() == "new filters") {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Success";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Filter status: " + itemToCheck.filter_status;
				return true;
			} else{
				if (itemToCheck.filter_status.ToLower() == "old")
				{

					pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
					pageManager.aiValidationPanel.aiValidateDetailsText.text = "Filter status: " + itemToCheck.filter_status;
					return false;
				}
				else
				{
                    pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
                    pageManager.aiValidationPanel.aiValidateDetailsText.text = "Filter status: Undetected";
                    return false;
                }
			}
		} else {
			return false;
		}
	}
	#endregion

